<script setup lang="ts">
import { ref, onBeforeUnmount } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import ProtectedImage from './ProtectedImage.vue'
import { communityApi } from '@/api/community'
import { socialApi } from '@/api/social'
import { useAuthStore } from '@/stores/auth'
import type { Post,PostComment } from '@/types/community'
import type { PublicUser } from '@/types/social'
const props=defineProps<{post:Post}>(),emit=defineEmits<{updated:[Post];removed:[number]}>()
const auth=useAuthStore(),router=useRouter()
const liking=ref(false),commentsOpen=ref(false),comments=ref<PostComment[]>([]),commentLoading=ref(false),commentError=ref(''),hasMore=ref(false),before=ref<number|null>(null),draft=ref(''),sending=ref(false),profile=ref<PublicUser|null>(null),profileOpen=ref(false),adding=ref(false)
let alive=true,commentSequence=0,retry:{clientRequestId:string;content:string}|null=null
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请重试'}
function time(value:string){return new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function like(){if(liking.value)return;liking.value=true;try{const result=await communityApi.like(props.post.id,!props.post.liked);if(alive)emit('updated',result)}catch(e){ElMessage.error(message(e))}finally{liking.value=false}}
async function remove(){try{await ElMessageBox.confirm('删除后动态将从墙上移除，其他人无法再读取其评论和图片。','删除自己的动态',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});await communityApi.remove(props.post.id);emit('removed',props.post.id)}catch(e){if(e instanceof Error)ElMessage.error(message(e))}}
async function loadComments(older=false){if(commentLoading.value)return;const run=++commentSequence;commentLoading.value=true;commentError.value='';try{const data=await communityApi.comments(props.post.id,older?before.value||undefined:undefined);if(!alive||run!==commentSequence)return;const seen=new Set(comments.value.map(c=>c.id));const newest=data.items.at(-1)?.id||0;comments.value=older?[...data.items.filter(c=>!seen.has(c.id)),...comments.value]:[...data.items,...comments.value.filter(c=>c.id>newest)];hasMore.value=data.hasMore;before.value=data.nextBeforeId}catch(e){if(alive)commentError.value=message(e)}finally{if(alive&&run===commentSequence)commentLoading.value=false}}
function toggleComments(){commentsOpen.value=!commentsOpen.value;if(commentsOpen.value)void loadComments()}
async function sendComment(){const content=draft.value.trim();if(!content||sending.value)return;if([...content].length>500){ElMessage.warning('评论最多500字');return}if(retry?.content!==content)retry={clientRequestId:crypto.randomUUID(),content};sending.value=true;commentError.value='';try{const row=await communityApi.comment(props.post.id,retry!);if(!alive)return;draft.value='';retry=null;if(!comments.value.some(c=>c.id===row.id))comments.value.push(row);const updated=await communityApi.get(props.post.id);if(alive)emit('updated',updated)}catch(e){if(alive)commentError.value=message(e)+'；可以重试'}finally{sending.value=false}}
async function removeComment(id:number){try{await ElMessageBox.confirm('删除自己的这条评论？','删除评论',{confirmButtonText:'删除',cancelButtonText:'取消'});await communityApi.removeComment(props.post.id,id);comments.value=comments.value.filter(c=>c.id!==id);const result=await communityApi.get(props.post.id);if(alive)emit('updated',result)}catch(e){if(e instanceof Error)ElMessage.error(message(e))}}
async function showProfile(user:PublicUser){profile.value=user;profileOpen.value=true;try{const result=await socialApi.user(user.id);if(alive&&profile.value?.id===user.id)profile.value=result}catch(e){ElMessage.error(message(e))}}
async function add(){if(!profile.value||adding.value)return;adding.value=true;try{await socialApi.add(profile.value.id);ElMessage.success('好友申请已发送')}catch(e){ElMessage.error(message(e))}finally{adding.value=false}}
onBeforeUnmount(()=>{alive=false;commentSequence++})
</script>
<template>
 <article class="post-card">
  <header><button class="author" @click="showProfile(post.author)"><el-avatar :size="44" :src="post.author.avatar"/><span><strong>{{post.author.nickname}}</strong><time>{{time(post.createdAt)}}</time></span></button><el-button v-if="post.author.id===auth.user?.id" text type="danger" size="small" @click="remove">删除</el-button></header>
  <p v-if="post.content" class="post-content">{{post.content}}</p>
  <div v-if="post.mediaIds.length" class="post-images" :class="{'one-image':post.mediaIds.length===1}"><ProtectedImage v-for="id in post.mediaIds" :key="id" :media-id="id"/></div>
  <footer><el-button text :class="{liked:post.liked}" :loading="liking" :aria-pressed="post.liked" @click="like">{{post.liked?'♥ 已赞':'♡ 点赞'}} {{post.likeCount||''}}</el-button><el-button text @click="toggleComments">{{commentsOpen?'收起评论':'评论'}} {{post.commentCount||''}}</el-button></footer>
  <section v-if="commentsOpen" class="post-comments"><el-alert v-if="commentError" :title="commentError" type="error" :closable="false"/><el-button v-if="hasMore" text :loading="commentLoading" @click="loadComments(true)">加载更早评论</el-button><p v-if="!comments.length&&!commentLoading" class="muted">还没有评论，来聊两句吧。</p><div v-for="c in comments" :key="c.id" class="comment"><button class="comment-author" @click="showProfile(c.author)">{{c.author.nickname}}</button><span>{{c.content}}</span><div><time>{{time(c.createdAt)}}</time><el-button v-if="c.author.id===auth.user?.id" text size="small" @click="removeComment(c.id)">删除</el-button></div></div><div class="comment-compose"><el-input v-model="draft" type="textarea" :rows="2" :maxlength="1000" :disabled="sending" placeholder="写下评论（最多500字）" resize="none"/><el-button :loading="sending" :disabled="!draft.trim()" @click="sendComment">发表评论</el-button></div><el-button v-if="commentError" text @click="loadComments()">刷新评论</el-button></section>
  <el-dialog v-model="profileOpen" title="作者资料" width="min(420px, 94vw)"><div v-if="profile" class="public-profile"><el-avatar :size="64" :src="profile.avatar"/><h3>{{profile.nickname}}</h3><p>{{profile.signature||'还没有个性签名'}}</p><small>ID {{profile.id}} · {{profile.online?'在线':'离线'}}</small><p>{{profile.totalGames}} 场游戏 · {{profile.winGames}} 场胜利</p><el-button v-if="profile.id!==auth.user?.id" type="primary" :loading="adding" @click="add">添加好友</el-button><el-button @click="profileOpen=false;router.push({name:'wall',query:{authorId:profile.id}})">查看 TA 的动态</el-button></div></el-dialog>
 </article>
</template>
<style scoped>
.post-card{border:1px solid var(--ww-border);border-radius:18px;background:rgba(20,27,47,.9);padding:24px;margin-bottom:18px}.post-card header{display:flex;align-items:center;justify-content:space-between}.author{display:flex;align-items:center;gap:12px;background:transparent;border:0;color:inherit;padding:0;text-align:left;cursor:pointer}.author>span{display:flex;flex-direction:column;gap:6px}.author strong{font-size:14px}.author time,.comment time,.muted{font-size:11px;color:var(--ww-text-dim)}.post-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px;margin:20px 0}.post-images{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:18px;align-items:start}.post-images :deep(a){display:block}.post-images :deep(img){width:100%;height:160px;object-fit:cover;background:#12182c}.post-images.one-image{grid-template-columns:minmax(0,400px)}.post-images.one-image :deep(img){height:auto;max-height:400px;max-width:100%;object-fit:contain}.post-card footer{display:flex;border-top:1px solid rgba(255,255,255,.06);margin-top:20px;padding-top:10px;gap:12px}.liked{color:#ee8dbd!important}.post-comments{padding-top:12px;border-top:1px solid var(--ww-border)}.comment{border-bottom:1px solid rgba(255,255,255,.04);padding:12px 0;font-size:13px;line-height:1.7}.comment>span{display:block;white-space:pre-wrap;overflow-wrap:anywhere}.comment>div{display:flex;gap:12px;align-items:center}.comment-author{border:0;background:transparent;color:#c6b2eb;padding:0;cursor:pointer;font-weight:600}.comment-compose{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.comment-compose>.el-button{margin-left:auto}.public-profile{text-align:center}.public-profile p{color:var(--ww-text-dim);overflow-wrap:anywhere}.public-profile small{color:var(--ww-moon)}
@media(max-width:680px){.post-card{padding:18px 14px;border-radius:14px}.post-images :deep(img){height:100px}.post-images{gap:6px}.post-content{font-size:14px}.post-card footer{margin-top:14px}}
</style>
